@model Umbraco.Bench.Umbraco.Models.Blocks.ImageBlockModel

<figure class="my-6">
    @if (Model.Image != null)
    {
        <img src="@Model.Image.GetCropUrl(width: 800)" alt="@Model.Caption" class="rounded-lg shadow-lg w-full h-auto">
    }
    @if (!string.IsNullOrEmpty(Model.Caption))
    {
        <figcaption class="text-center text-gray-500 mt-2 italic">@Model.Caption</figcaption>
    }
</figure>

@model Umbraco.Bench.Umbraco.Models.Blocks.QuoteBlockModel

<blockquote class="border-l-4 border-gray-300 pl-6 my-6 italic">
    <p class="text-xl">@Model.Quote</p>
    @if (!string.IsNullOrEmpty(Model.Attribution))
    {
        <footer class="mt-2 text-gray-600">— @Model.Attribution</footer>
    }
</blockquote>

